"use client";

import { Plus, Eye, Edit, Trash2, AlertTriangle } from "lucide-react";

export default function AgentSidebar({
  agents,
  canvasOrder = [],
  categoryColors,
  onAddAgent,
  onViewDetails,
  onEdit,
  onRemove,
}) {
  const canvasSet = new Set(canvasOrder);

  const handleDragStart = (e, agentId) => {
    e.dataTransfer.setData("agent-id", agentId.toString());
    e.dataTransfer.effectAllowed = "copy";
  };

  // Detect issues with an agent
  const getAgentIssues = (agent) => {
    const issues = [];

    // Check for missing sub-agents
    if (agent.subAgents && agent.subAgents.length > 0) {
      const missingSubs = agent.subAgents.filter(
        (subId) => !agents.find((a) => a.id === subId),
      );
      if (missingSubs.length > 0) {
        issues.push(`Sub-agent(s) manquant(s): ${missingSubs.join(", ")}`);
      }
    }

    // Check for missing model
    if (!agent.agent_model || agent.agent_model.trim() === "") {
      issues.push("Modèle non défini");
    }

    // Check if Sequential/Parallel has no sub-agents
    if (
      (agent.category === "Sequential" || agent.category === "Parallel") &&
      (!agent.subAgents || agent.subAgents.length === 0)
    ) {
      issues.push(`Agent ${agent.category} sans sub-agents`);
    }

    return issues;
  };

  return (
    <div className="w-72 bg-gray-800 rounded-xl p-4 flex flex-col h-full">
      <div className="flex items-center justify-between mb-4">
        <h2 className="text-lg font-bold text-white">Agents</h2>
        <button
          onClick={onAddAgent}
          className="flex items-center gap-1 bg-[#013DFF] hover:bg-blue-700 text-white px-3 py-2 rounded-lg transition-colors text-sm"
        >
          <Plus size={16} />
          Add
        </button>
      </div>

      <p className="text-xs text-gray-400 mb-3">
        Drag an agent onto the canvas to place it
      </p>

      <div className="flex-1 overflow-y-auto space-y-2">
        {agents.length === 0 && (
          <p className="text-gray-500 text-sm text-center mt-8">
            No agents yet. Click &quot;Add&quot; to create one.
          </p>
        )}

        {agents.map((agent) => {
          const isOnCanvas = canvasSet.has(agent.id);
          const issues = getAgentIssues(agent);
          const hasIssues = issues.length > 0;

          return (
            <div
              key={agent.id}
              draggable={!isOnCanvas}
              onDragStart={(e) => handleDragStart(e, agent.id)}
              className={`rounded-lg p-3 border-2 transition-colors ${
                isOnCanvas
                  ? "border-gray-600 bg-gray-700 opacity-50 cursor-default"
                  : hasIssues
                    ? "border-yellow-500/50 bg-gray-700 hover:border-yellow-500 cursor-grab active:cursor-grabbing"
                    : "border-gray-600 bg-gray-700 hover:border-gray-500 cursor-grab active:cursor-grabbing"
              }`}
            >
              <div className="flex items-center gap-2">
                <div
                  className={`w-3 h-3 rounded-full ${categoryColors[agent.category] || "bg-gray-500"}`}
                />
                <span className="text-white text-sm font-medium flex-1 truncate">
                  {agent.label}
                </span>
                {/* Warning badge */}
                {hasIssues && (
                  <div className="relative group">
                    <div className="p-0.5 bg-yellow-500 rounded-full cursor-help">
                      <AlertTriangle size={10} className="text-yellow-900" />
                    </div>
                    {/* Tooltip */}
                    <div className="absolute right-0 top-full mt-1 z-50 hidden group-hover:block w-max max-w-[220px]">
                      <div className="bg-gray-900 text-white text-xs rounded-lg p-2 shadow-lg border border-yellow-500">
                        <p className="font-semibold text-yellow-400 mb-1">
                          ⚠️ Problème(s)
                        </p>
                        <ul className="list-disc list-inside space-y-0.5">
                          {issues.map((issue, i) => (
                            <li key={i} className="text-[10px]">
                              {issue}
                            </li>
                          ))}
                        </ul>
                      </div>
                    </div>
                  </div>
                )}
                {isOnCanvas && (
                  <span className="text-[10px] text-gray-400 bg-gray-600 px-1.5 py-0.5 rounded">
                    on canvas
                  </span>
                )}
              </div>
              <p className="text-xs text-gray-400 mt-1 ml-5">
                {agent.category}
                {agent.subAgents.length > 0 &&
                  ` • ${agent.subAgents.length} sub-agent(s)`}
              </p>
              <div className="flex gap-1 mt-2 ml-4">
                <button
                  onClick={() => onViewDetails(agent.id)}
                  className="text-gray-400 hover:text-white p-1 rounded hover:bg-gray-600 transition-colors"
                  title="View Details"
                >
                  <Eye size={14} />
                </button>
                <button
                  onClick={() => onEdit(agent)}
                  className="text-gray-400 hover:text-white p-1 rounded hover:bg-gray-600 transition-colors"
                  title="Edit"
                >
                  <Edit size={14} />
                </button>
                <button
                  onClick={() => onRemove(agent.id)}
                  className="text-gray-400 hover:text-red-400 p-1 rounded hover:bg-gray-600 transition-colors"
                  title="Delete"
                >
                  <Trash2 size={14} />
                </button>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}
