"use client";

import React, { useState, useEffect, useCallback } from "react";
import AgentSidebar from "./AgentSidebar";
import AgentCanvas from "./AgentCanvas";
import AgentModal from "./AgentModal";
import AgentDetailsModal from "./AgentDetailsModal";
import ConfirmToast from "./ConfirmToast";
import {
  listAgents,
  createAgent as apiCreateAgent,
  deleteAgent as apiDeleteAgent,
  listTools,
  createSession,
  runAgent as apiRunAgent,
} from "@/lib/api";

const categories = ["Base", "Parallel", "Sequential", "Loop"];

const categoryColors = {
  Base: "bg-blue-500",
  Parallel: "bg-green-500",
  Sequential: "bg-purple-500",
  Loop: "bg-orange-500",
};

const typeToCategory = {
  base: "Base",
  parallel: "Parallel",
  sequential: "Sequential",
  loop: "Loop",
};

function parseSubAgents(raw) {
  if (!raw) return [];
  if (Array.isArray(raw)) return raw;
  // Handle string like "['agent46', 'agent61']" or '["agent46", "agent61"]'
  if (typeof raw === "string") {
    try {
      // Replace Python-style single quotes with double quotes for JSON parsing
      const jsonStr = raw.replace(/'/g, '"');
      const parsed = JSON.parse(jsonStr);
      return Array.isArray(parsed) ? parsed : [];
    } catch {
      return [];
    }
  }
  return [];
}

function mapApiAgent(a) {
  const category = typeToCategory[a.agent_type] || "Base";
  const subAgents = parseSubAgents(a.sub_agents);
  return {
    id: a.agent_name,
    label: a.agent_name,
    x: 0,
    y: 0,
    color: categoryColors[category] || "bg-gray-500",
    selectedTool: (a.agent_tools && a.agent_tools[0]) || "",
    category,
    subAgents: [...new Set(subAgents)],
    agent_model: a.agent_model || "",
    agent_description: a.agent_description || "",
    agent_instruction: a.agent_instruction || "",
    agent_tools: a.agent_tools || [],
    organization_id: a.organization_id || "",
    owner_id: a.owner_id || "",
  };
}

export default function AgentDiagram() {
  const [boxes, setBoxes] = useState([]);
  const [canvasOrder, setCanvasOrder] = useState([]);
  const [availableTools, setAvailableTools] = useState([]);
  const [loading, setLoading] = useState(true);

  const [showModal, setShowModal] = useState(false);
  const [showDetailsModal, setShowDetailsModal] = useState(false);
  const [viewingAgent, setViewingAgent] = useState(null);
  const [editingAgent, setEditingAgent] = useState(null);
  const [newAgent, setNewAgent] = useState({
    name: "",
    category: "",
    subAgents: [],
    agent_model: "",
    agent_description: "",
    agent_instruction: "",
    agent_tools: [],
    organization_id: "",
    owner_id: "",
  });
  const [deleteConfirm, setDeleteConfirm] = useState(null);

  // --- Fetch data on mount ---
  const fetchAgents = useCallback(async () => {
    try {
      const data = await listAgents();
      const agents = Array.isArray(data) ? data : [];
      console.log("[fetchAgents] raw API response:", data);
      agents.forEach((a) => {
        console.log(
          `[fetchAgents] agent="${a.agent_name}" sub_agents=(${(a.sub_agents || []).length}):`,
          a.sub_agents,
        );
      });
      setBoxes(agents.map(mapApiAgent));
      // Clean canvasOrder: remove IDs that no longer exist
      const agentIds = new Set(agents.map((a) => a.agent_name));
      setCanvasOrder((prev) => prev.filter((id) => agentIds.has(id)));
    } catch (err) {
      console.error("Failed to fetch agents:", err);
    }
  }, []);

  const fetchTools = useCallback(async () => {
    try {
      const data = await listTools();
      const tools = Array.isArray(data)
        ? data.map((t) => t.tool_name || t.name || t)
        : [];
      setAvailableTools(tools);
    } catch (err) {
      console.error("Failed to fetch tools:", err);
    }
  }, []);

  useEffect(() => {
    Promise.all([fetchAgents(), fetchTools()]).finally(() => setLoading(false));
  }, [fetchAgents, fetchTools]);

  // --- Canvas order: ordered list of agent IDs on the diagram ---
  const canvasBoxes = canvasOrder
    .map((id) => boxes.find((b) => b.id === id))
    .filter(Boolean);

  // --- Modal handlers ---
  const openModal = () => {
    setEditingAgent(null);
    setNewAgent({
      name: "",
      category: "",
      subAgents: [],
      agent_model: "",
      agent_description: "",
      agent_instruction: "",
      agent_tools: [],
      organization_id: "",
      owner_id: "",
    });
    setShowModal(true);
  };

  const openEditModal = (box) => {
    setEditingAgent(box.id);
    setNewAgent({
      name: box.label,
      category: box.category,
      subAgents: [...box.subAgents],
      agent_model: box.agent_model || "",
      agent_description: box.agent_description || "",
      agent_instruction: box.agent_instruction || "",
      agent_tools: box.agent_tools || [],
      organization_id: box.organization_id || "",
      owner_id: box.owner_id || "",
    });
    setShowModal(true);
  };

  const closeModal = () => {
    setShowModal(false);
    setEditingAgent(null);
  };

  const openDetailsModal = (agentId) => {
    const agent = boxes.find((b) => b.id === agentId);
    setViewingAgent(agent);
    setShowDetailsModal(true);
  };

  const closeDetailsModal = () => {
    setShowDetailsModal(false);
    setViewingAgent(null);
  };

  const handleViewSubAgent = (subId) => {
    closeDetailsModal();
    setTimeout(() => openDetailsModal(subId), 100);
  };

  // --- CRUD ---
  const saveAgent = async () => {
    if (!newAgent.name.trim()) {
      alert("Please enter an agent name");
      return;
    }
    if (!newAgent.category) {
      alert("Please select a category");
      return;
    }
    if (["Sequential", "Parallel"].includes(newAgent.category)) {
      if (newAgent.subAgents.length < 2) {
        alert(`${newAgent.category} agents require at least 2 sub-agents`);
        return;
      }
      if (newAgent.subAgents.length > 6) {
        alert(`${newAgent.category} agents can have maximum 6 sub-agents`);
        return;
      }
    }

    if (editingAgent) {
      setBoxes(
        boxes.map((box) =>
          box.id === editingAgent
            ? {
                ...box,
                label: newAgent.name,
                category: newAgent.category,
                color: categoryColors[newAgent.category] || "bg-gray-500",
                subAgents: newAgent.subAgents,
                agent_model: newAgent.agent_model,
                agent_description: newAgent.agent_description,
                agent_instruction: newAgent.agent_instruction,
                agent_tools: newAgent.agent_tools,
                organization_id: newAgent.organization_id,
                owner_id: newAgent.owner_id,
              }
            : box,
        ),
      );
    } else {
      try {
        const payload = {
          agent_name: newAgent.name,
          agent_model: newAgent.agent_model,
          agent_description: newAgent.agent_description,
          agent_instruction: newAgent.agent_instruction,
          agent_tools: newAgent.agent_tools,
          agent_type: newAgent.category.toLowerCase(),
          sub_agents: newAgent.subAgents,
          organization_id: newAgent.organization_id,
          owner_id: newAgent.owner_id,
        };
        await apiCreateAgent(payload);
        await fetchAgents();
      } catch (err) {
        alert(`Failed to create agent: ${err.message}`);
        return;
      }
    }
    closeModal();
  };

  const requestDelete = (id) => {
    const agent = boxes.find((b) => b.id === id);
    setDeleteConfirm({ id, label: agent?.label || "this agent" });
  };

  const confirmDelete = async () => {
    if (!deleteConfirm) return;
    const id = deleteConfirm.id;
    try {
      await apiDeleteAgent(id);
      setCanvasOrder((prev) => prev.filter((cid) => cid !== id));
      await fetchAgents();
    } catch (err) {
      console.error("Failed to delete agent:", err);
      setBoxes(
        boxes
          .filter((box) => box.id !== id)
          .map((box) => ({
            ...box,
            subAgents: box.subAgents.filter((subId) => subId !== id),
          })),
      );
      setCanvasOrder((prev) => prev.filter((cid) => cid !== id));
    }
    setDeleteConfirm(null);
  };

  const cancelDelete = () => {
    setDeleteConfirm(null);
  };

  const removeFromCanvas = (id) => {
    setCanvasOrder((prev) => prev.filter((cid) => cid !== id));
  };

  const handleToolChange = (id, tool) => {
    setBoxes(
      boxes.map((box) =>
        box.id === id ? { ...box, selectedTool: tool } : box,
      ),
    );
  };

  const handleRun = async (box) => {
    const sessionId = `session_${box.id}_${Date.now()}`;
    const userId = box.owner_id || "user@example.com";

    try {
      await createSession({
        agent_name: box.label,
        user_id: userId,
        session_id: sessionId,
      });

      const result = await apiRunAgent({
        agent_name: box.label,
        user_id: userId,
        session_id: sessionId,
        run_mode: "run",
        new_message: {
          role: "user",
          parts: [{ text: "Run agent" }],
        },
      });

      alert(
        `Agent "${box.label}" ran successfully.\n\n${JSON.stringify(result, null, 2)}`,
      );
    } catch (err) {
      alert(`Failed to run agent: ${err.message}`);
    }
  };

  // --- Sidebar → Canvas drop (sequential: append to order) ---
  const handleDropFromSidebar = (agentId) => {
    if (canvasOrder.includes(agentId)) return;
    setCanvasOrder((prev) => [...prev, agentId]);
  };

  // --- Reorder within canvas ---
  const handleReorderCanvas = (fromIndex, toIndex) => {
    setCanvasOrder((prev) => {
      const next = [...prev];
      const [moved] = next.splice(fromIndex, 1);
      next.splice(toIndex, 0, moved);
      return next;
    });
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-gray-900 to-gray-800 flex items-center justify-center">
        <p className="text-white text-xl">Loading agents...</p>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-900 to-gray-800 p-8">
      <div className="max-w-7xl mx-auto">
        <h1 className="text-4xl font-bold text-white mb-6">
          Agent Card Diagram
        </h1>

        <div className="flex gap-6" style={{ height: "700px" }}>
          <AgentSidebar
            agents={boxes}
            canvasOrder={canvasOrder}
            categoryColors={categoryColors}
            onAddAgent={openModal}
            onViewDetails={openDetailsModal}
            onEdit={openEditModal}
            onRemove={requestDelete}
          />

          <AgentCanvas
            boxes={boxes}
            canvasBoxes={canvasBoxes}
            availableTools={availableTools}
            onToolChange={handleToolChange}
            onRun={handleRun}
            onViewDetails={openDetailsModal}
            onEdit={openEditModal}
            onRemoveFromCanvas={removeFromCanvas}
            onDropFromSidebar={handleDropFromSidebar}
            onReorderCanvas={handleReorderCanvas}
          />
        </div>

        <div className="mt-6 bg-gray-800 rounded-lg p-6 text-gray-300">
          <p className="font-semibold mb-3 text-lg">Agent Categories:</p>
          <div className="grid grid-cols-2 gap-3 mb-4">
            <div className="flex items-center gap-2">
              <div className="w-4 h-4 bg-blue-500 rounded"></div>
              <span>
                <strong>Base:</strong> Single task agent
              </span>
            </div>
            <div className="flex items-center gap-2">
              <div className="w-4 h-4 bg-green-500 rounded"></div>
              <span>
                <strong>Parallel:</strong> Sub-agents shown side-by-side
              </span>
            </div>
            <div className="flex items-center gap-2">
              <div className="w-4 h-4 bg-purple-500 rounded"></div>
              <span>
                <strong>Sequential:</strong> Sub-agents shown with arrows (↓)
              </span>
            </div>
            <div className="flex items-center gap-2">
              <div className="w-4 h-4 bg-orange-500 rounded"></div>
              <span>
                <strong>Loop:</strong> Repeats sub-agents
              </span>
            </div>
          </div>
          <p className="font-semibold mb-2 text-lg">Instructions:</p>
          <ul className="space-y-2">
            <li>
              • Create agents using the sidebar, then drag them onto the diagram
            </li>
            <li>• Agents are arranged sequentially (top → bottom)</li>
            <li>• Drag agents within the diagram to reorder them</li>
            <li>
              • Click X to remove an agent from the diagram (keeps it in
              sidebar)
            </li>
          </ul>
        </div>
      </div>

      {showDetailsModal && viewingAgent && (
        <AgentDetailsModal
          agent={viewingAgent}
          boxes={boxes}
          onClose={closeDetailsModal}
          onViewSubAgent={handleViewSubAgent}
        />
      )}

      <AgentModal
        show={showModal}
        editingAgent={editingAgent}
        newAgent={newAgent}
        setNewAgent={setNewAgent}
        boxes={boxes}
        categories={categories}
        availableTools={availableTools}
        onClose={closeModal}
        onSave={saveAgent}
      />

      {deleteConfirm && (
        <ConfirmToast
          message={`Delete "${deleteConfirm.label}" permanently?`}
          onConfirm={confirmDelete}
          onCancel={cancelDelete}
        />
      )}
    </div>
  );
}
