"use client";

import { useState, useEffect, useCallback, useRef } from "react";
import { X, Plus, Save, ChevronDown, ChevronUp } from "lucide-react";
import AgentSidebar from "./AgentSidebar";
import AgentCanvas from "./AgentCanvas";
import AgentDetailsModal from "./AgentDetailsModal";
import AgentModal from "./AgentModal";
import ConfirmToast from "./ConfirmToast";
import WorkflowPanel from "./WorkflowPanel";
import {
  listAgents,
  listTools,
  createAgent as apiCreateAgent,
  deleteAgent as apiDeleteAgent,
  createSession,
  runAgent as apiRunAgent,
} from "@/lib/api";
import { runWorkflow } from "@/lib/workflowRunner";

const categoryColors = {
  Base: "bg-blue-500",
  Parallel: "bg-green-500",
  Sequential: "bg-purple-500",
  Loop: "bg-orange-500",
};

const typeToCategory = {
  base: "Base",
  parallel: "Parallel",
  sequential: "Sequential",
  loop: "Loop",
};

function parseSubAgents(raw) {
  if (!raw) return [];
  if (Array.isArray(raw)) return raw;
  if (typeof raw === "string") {
    // Handle Python None string
    if (raw === "None" || raw === "null" || raw.trim() === "") return [];
    try {
      // Replace both Python-style single quotes and unicode escaped quotes
      let jsonStr = raw.replace(/'/g, '"').replace(/\\u0027/g, '"');
      const parsed = JSON.parse(jsonStr);
      console.log("[parseSubAgents] parsed:", parsed);
      return Array.isArray(parsed) ? parsed : [];
    } catch (e) {
      console.error("[parseSubAgents] failed to parse:", raw, e);
      return [];
    }
  }
  return [];
}

function parseTools(raw) {
  if (!raw) return [];
  if (Array.isArray(raw)) return raw;
  if (typeof raw === "string") {
    if (raw === "None" || raw === "null" || raw.trim() === "" || raw === "[]")
      return [];
    try {
      let jsonStr = raw.replace(/'/g, '"').replace(/\\u0027/g, '"');
      const parsed = JSON.parse(jsonStr);
      return Array.isArray(parsed) ? parsed : [];
    } catch {
      return [];
    }
  }
  return [];
}

function mapApiAgent(a) {
  const category = typeToCategory[a.agent_type] || "Base";
  const subAgents = parseSubAgents(a.sub_agents);
  const tools = parseTools(a.agent_tools);
  const agentId = a.agent_id != null ? `agent${a.agent_id}` : a.agent_name;
  return {
    id: agentId,
    label: a.agent_name,
    x: 0,
    y: 0,
    color: categoryColors[category] || "bg-gray-500",
    selectedTool: (tools && tools[0]) || "",
    category,
    subAgents: [...new Set(subAgents)],
    agent_model: a.agent_model || "",
    agent_description: a.agent_description || "",
    agent_instruction: a.agent_instruction || "",
    agent_tools: tools,
    organization_id: a.organization_id || "",
    owner_id: a.owner_id || "",
  };
}

function createEmptyAgentData() {
  return {
    agent_name: "",
    agent_model: "",
    agent_description: "",
    agent_instruction: "",
    agent_tools: [],
    organization_id: "",
    owner_id: "",
    agent_type: "sequential",
  };
}

export default function DiagramEditor() {
  // Tab state: each tab has { id, agentData, canvasOrder, isNew, isDirty }
  const [tabs, setTabs] = useState([
    {
      id: "new",
      agentData: createEmptyAgentData(),
      canvasOrder: [],
      isNew: true,
      isDirty: false,
    },
  ]);
  const [activeTabId, setActiveTabId] = useState("new");
  const [allAgents, setAllAgents] = useState([]);
  const [availableTools, setAvailableTools] = useState([]);
  const [loading, setLoading] = useState(true);
  const [expandedHeader, setExpandedHeader] = useState(true);
  const [isSaving, setIsSaving] = useState(false);

  // Workflow execution
  const [workflowState, setWorkflowState] = useState({
    status: "idle", // idle | running | done | error
    steps: [], // [{ id, label, type, status, result, error, startTime, duration }]
    error: null,
  });
  const abortRef = useRef(null);

  // Modals
  const [showDetailsModal, setShowDetailsModal] = useState(false);
  const [viewingAgent, setViewingAgent] = useState(null);
  const [deleteConfirm, setDeleteConfirm] = useState(null);

  // Create Agent Modal
  const [showCreateModal, setShowCreateModal] = useState(false);
  const defaultNewAgent = {
    name: "",
    category: "Base",
    agent_model: "",
    agent_description: "",
    agent_instruction: "",
    agent_tools: [],
    organization_id: "",
    owner_id: "",
    subAgents: [],
  };
  const [newAgent, setNewAgent] = useState(defaultNewAgent);

  // Get current tab
  const activeTab = tabs.find((t) => t.id === activeTabId);
  const boxes = allAgents.map(mapApiAgent);
  const canvasBoxes = activeTab
    ? activeTab.canvasOrder
        .map((id) => boxes.find((b) => b.id === id))
        .filter(Boolean)
    : [];

  // Fetch all agents and tools on mount
  const fetchData = useCallback(async () => {
    try {
      const [agents, tools] = await Promise.all([listAgents(), listTools()]);
      setAllAgents(Array.isArray(agents) ? agents : []);
      const toolNames = Array.isArray(tools)
        ? tools.map((t) => t.tool_name || t.name || t)
        : [];
      setAvailableTools(toolNames);
    } catch (err) {
      console.error("Failed to fetch data:", err);
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchData();
  }, [fetchData]);

  // Update active tab's agentData
  const updateAgentData = (newData) => {
    setTabs((prev) =>
      prev.map((t) =>
        t.id === activeTabId ? { ...t, agentData: newData, isDirty: true } : t,
      ),
    );
  };

  // Update active tab's canvasOrder
  const updateCanvasOrder = (newOrder) => {
    setTabs((prev) =>
      prev.map((t) =>
        t.id === activeTabId
          ? { ...t, canvasOrder: newOrder, isDirty: true }
          : t,
      ),
    );
  };

  // Open a new tab for an existing agent
  const openAgentTab = (agentId) => {
    // Check if already open by ID
    const existingById = tabs.find((t) => t.id === agentId);
    if (existingById) {
      setActiveTabId(agentId);
      return;
    }

    // Also check by agent name (in case tab was saved and ID changed)
    const existingByName = tabs.find(
      (t) => t.agentData?.agent_name === agentId,
    );
    if (existingByName) {
      setActiveTabId(existingByName.id);
      return;
    }

    // Find agent in list
    const agent = allAgents.find((a) => a.agent_name === agentId);
    if (agent) {
      setTabs((prev) => [
        ...prev,
        {
          id: agentId,
          agentData: {
            agent_name: agent.agent_name || "",
            agent_model: agent.agent_model || "",
            agent_description: agent.agent_description || "",
            agent_instruction: agent.agent_instruction || "",
            agent_tools: agent.agent_tools || [],
            organization_id: agent.organization_id || "",
            owner_id: agent.owner_id || "",
            agent_type: agent.agent_type || "sequential",
          },
          canvasOrder: parseSubAgents(agent.sub_agents),
          isNew: false,
          isDirty: false,
        },
      ]);
      setActiveTabId(agentId);
    }
  };

  // Create a new empty tab
  const createNewTab = () => {
    const newId = `new-${Date.now()}`;
    setTabs((prev) => [
      ...prev,
      {
        id: newId,
        agentData: createEmptyAgentData(),
        canvasOrder: [],
        isNew: true,
        isDirty: false,
      },
    ]);
    setActiveTabId(newId);
  };

  // Close a tab
  const closeTab = (tabId) => {
    const tab = tabs.find((t) => t.id === tabId);
    if (tab?.isDirty) {
      if (!confirm("You have unsaved changes. Close anyway?")) {
        return;
      }
    }
    const remaining = tabs.filter((t) => t.id !== tabId);
    setTabs(remaining);
    if (activeTabId === tabId && remaining.length > 0) {
      setActiveTabId(remaining[0].id);
    }
  };

  // Save current tab
  const handleSave = async () => {
    if (!activeTab) return;
    const { agentData, canvasOrder } = activeTab;

    if (!agentData.agent_name.trim()) {
      alert("Please enter an agent name");
      return;
    }
    if (!agentData.agent_model.trim()) {
      alert("Please enter a model");
      return;
    }
    if (!agentData.organization_id.trim()) {
      alert("Please enter an organization");
      return;
    }
    if (!agentData.owner_id.trim()) {
      alert("Please enter an owner email");
      return;
    }

    setIsSaving(true);
    try {
      const payload = {
        agent_model: agentData.agent_model,
        agent_description: agentData.agent_description,
        agent_instruction: agentData.agent_instruction,
        agent_tools: agentData.agent_tools,
        agent_type: agentData.agent_type || "sequential",
        sub_agents: canvasOrder,
        organization_id: agentData.organization_id,
        owner_id: agentData.owner_id,
      };
      const result = await apiCreateAgent(payload);
      const newId = result.agent_id || agentData.agent_name;

      // Update tab
      setTabs((prev) =>
        prev.map((t) =>
          t.id === activeTabId
            ? { ...t, id: newId, isNew: false, isDirty: false }
            : t,
        ),
      );
      if (activeTabId !== newId) {
        setActiveTabId(newId);
      }
      fetchData(); // Refresh agent list
    } catch (err) {
      alert(`Failed to save agent: ${err.message}`);
    } finally {
      setIsSaving(false);
    }
  };

  // Canvas handlers
  const handleDropFromSidebar = (agentId) => {
    if (!activeTab || activeTab.canvasOrder.includes(agentId)) return;
    updateCanvasOrder([...activeTab.canvasOrder, agentId]);
  };

  const handleReorderCanvas = (fromIndex, toIndex) => {
    if (!activeTab) return;
    const next = [...activeTab.canvasOrder];
    const [moved] = next.splice(fromIndex, 1);
    next.splice(toIndex, 0, moved);
    updateCanvasOrder(next);
  };

  const removeFromCanvas = (id) => {
    if (!activeTab) return;
    updateCanvasOrder(activeTab.canvasOrder.filter((cid) => cid !== id));
  };

  const handleDoubleClickAgent = (agentId) => {
    const agent = boxes.find((b) => b.id === agentId);
    if (agent && agent.category === "Sequential") {
      openAgentTab(agentId);
    }
  };

  // Details modal
  const openDetailsModal = (agentId) => {
    const agent = boxes.find((b) => b.id === agentId);
    setViewingAgent(agent);
    setShowDetailsModal(true);
  };

  const closeDetailsModal = () => {
    setShowDetailsModal(false);
    setViewingAgent(null);
  };

  // Run handler
  const handleRun = async (box) => {
    const userId = box.owner_id || "user@example.com";

    try {
      await createSession({
        agent_name: box.id,
        user_id: userId,
        session_id: box.id,
      });

      const result = await apiRunAgent({
        agent_name: box.id,
        user_id: userId,
        session_id: box.id,
        run_mode: "run",
        new_message: { role: "user", parts: [{ text: "Run agent" }] },
      });

      alert(
        `Agent "${box.label}" ran successfully.\n\n${JSON.stringify(result, null, 2)}`,
      );
    } catch (err) {
      alert(`Failed to run agent: ${err.message}`);
    }
  };

  // Delete handler
  const requestDelete = (id) => {
    const agent = boxes.find((b) => b.id === id);
    setDeleteConfirm({ id, label: agent?.label || "this agent" });
  };

  const confirmDelete = async () => {
    if (!deleteConfirm) return;
    const id = deleteConfirm.id;
    try {
      await apiDeleteAgent(id);
      // Remove from canvas if present
      if (activeTab) {
        updateCanvasOrder(activeTab.canvasOrder.filter((cid) => cid !== id));
      }
      fetchData();
    } catch (err) {
      console.error("Failed to delete agent:", err);
    }
    setDeleteConfirm(null);
  };

  const cancelDelete = () => setDeleteConfirm(null);

  // Create Agent Modal handlers
  const openCreateModal = () => {
    setNewAgent({ ...defaultNewAgent });
    setShowCreateModal(true);
  };

  const closeCreateModal = () => {
    setShowCreateModal(false);
  };

  const handleCreateFromModal = async () => {
    if (!newAgent.name.trim()) {
      alert("Please enter an agent name");
      return;
    }
    const categoryToType = { Base: "base", Sequential: "sequential", Parallel: "parallel", Loop: "loop" };
    try {
      await apiCreateAgent({
        agent_name: newAgent.name,
        agent_model: newAgent.agent_model,
        agent_description: newAgent.agent_description,
        agent_instruction: newAgent.agent_instruction,
        agent_tools: newAgent.agent_tools,
        agent_type: categoryToType[newAgent.category] || "base",
        sub_agents: newAgent.subAgents,
        organization_id: newAgent.organization_id,
        owner_id: newAgent.owner_id,
      });
      setShowCreateModal(false);
      fetchData();
    } catch (err) {
      alert(`Failed to create agent: ${err.message}`);
    }
  };

  // --- Workflow execution ---
  const handleRunWorkflow = async () => {
    if (!activeTab || activeTab.canvasOrder.length === 0) return;

    const agentsMap = new Map(boxes.map((b) => [b.id, b]));
    const controller = new AbortController();
    abortRef.current = controller;

    // Initialize steps from canvasOrder
    const initialSteps = activeTab.canvasOrder.map((id) => ({
      id,
      label: agentsMap.get(id)?.label || id,
      type: agentsMap.get(id)?.category?.toLowerCase() || "base",
      status: "pending",
      result: null,
      error: null,
      startTime: null,
      duration: null,
    }));

    setWorkflowState({ status: "running", steps: initialSteps, error: null });

    const callbacks = {
      onStepStart: (agentId, type) => {
        setWorkflowState((prev) => ({
          ...prev,
          steps: prev.steps.map((s) =>
            s.id === agentId
              ? { ...s, status: "running", startTime: Date.now() }
              : s,
          ),
        }));
      },
      onStepComplete: (agentId, result) => {
        setWorkflowState((prev) => ({
          ...prev,
          steps: prev.steps.map((s) =>
            s.id === agentId
              ? {
                  ...s,
                  status: "done",
                  result,
                  duration: s.startTime ? Date.now() - s.startTime : null,
                }
              : s,
          ),
        }));
      },
      onStepError: (agentId, err) => {
        setWorkflowState((prev) => ({
          ...prev,
          steps: prev.steps.map((s) =>
            s.id === agentId
              ? {
                  ...s,
                  status: "error",
                  error: err.message,
                  duration: s.startTime ? Date.now() - s.startTime : null,
                }
              : s,
          ),
        }));
      },
      onWorkflowStart: () => {},
      onWorkflowComplete: () => {
        setWorkflowState((prev) => ({ ...prev, status: "done" }));
      },
      onWorkflowError: (err) => {
        setWorkflowState((prev) => ({
          ...prev,
          status: "error",
          error: err.name === "AbortError" ? "Workflow stopped" : err.message,
        }));
      },
    };

    try {
      await runWorkflow(
        activeTab.canvasOrder,
        agentsMap,
        callbacks,
        controller.signal,
      );
    } catch {
      // Error already handled in callbacks
    }
  };

  const handleStopWorkflow = () => {
    abortRef.current?.abort();
  };

  if (loading) {
    return (
      <div className="min-h-screen bg-gradient-to-br from-gray-900 to-gray-800 flex items-center justify-center">
        <p className="text-white text-xl">Loading...</p>
      </div>
    );
  }

  return (
    <div className="min-h-screen bg-gradient-to-br from-gray-900 to-gray-800 p-6">
      <div className="flex gap-6 h-[calc(100vh-3rem)]">
        {/* Left: Agent Sidebar */}
        <AgentSidebar
          agents={boxes}
          canvasOrder={activeTab?.canvasOrder || []}
          categoryColors={categoryColors}
          onAddAgent={openCreateModal}
          onViewDetails={openDetailsModal}
          onEdit={(box) => openAgentTab(box.id)}
          onRemove={requestDelete}
        />

        {/* Right: Tabs + Header + Canvas */}
        <div className="flex-1 flex flex-col bg-gray-800 rounded-xl overflow-hidden">
          {/* Tab Bar */}
          <div className="bg-gray-700 border-b border-gray-600 flex items-center px-2 shrink-0">
            <div className="flex-1 flex items-center overflow-x-auto">
              {tabs.map((tab) => (
                <div
                  key={tab.id}
                  className={`flex items-center gap-2 px-4 py-2 cursor-pointer border-b-2 transition-colors ${
                    activeTabId === tab.id
                      ? "border-purple-500 bg-gray-800 text-white"
                      : "border-transparent text-gray-400 hover:text-white hover:bg-gray-700/50"
                  }`}
                  onClick={() => setActiveTabId(tab.id)}
                >
                  <span className="truncate max-w-[150px]">
                    {tab.agentData.agent_name || "New Agent"}
                    {tab.isDirty && " •"}
                  </span>
                  {tabs.length > 1 && (
                    <button
                      onClick={(e) => {
                        e.stopPropagation();
                        closeTab(tab.id);
                      }}
                      className="p-1 hover:bg-gray-600 rounded"
                    >
                      <X size={14} />
                    </button>
                  )}
                </div>
              ))}
            </div>
            <button
              onClick={createNewTab}
              className="p-2 text-gray-400 hover:text-white hover:bg-gray-600 rounded"
              title="New Agent"
            >
              <Plus size={18} />
            </button>
          </div>

          {/* Agent Header */}
          {activeTab && (
            <div className="bg-gray-800 border-b border-gray-700 shrink-0">
              <div className="flex items-center justify-between px-4 py-2">
                <div className="flex items-center gap-3 flex-1">
                  <input
                    type="text"
                    value={activeTab.agentData.agent_name || ""}
                    onChange={(e) =>
                      updateAgentData({
                        ...activeTab.agentData,
                        agent_name: e.target.value,
                      })
                    }
                    placeholder="Agent Name"
                    className="text-xl font-bold bg-transparent text-white border-b border-transparent hover:border-gray-500 focus:border-purple-500 focus:outline-none px-1"
                  />
                  <select
                    value={activeTab.agentData.agent_type || "sequential"}
                    onChange={(e) =>
                      updateAgentData({
                        ...activeTab.agentData,
                        agent_type: e.target.value,
                      })
                    }
                    className={`text-xs px-2 py-1 rounded text-white cursor-pointer border-none focus:outline-none ${
                      activeTab.agentData.agent_type === "parallel"
                        ? "bg-green-600"
                        : activeTab.agentData.agent_type === "loop"
                          ? "bg-orange-600"
                          : activeTab.agentData.agent_type === "base"
                            ? "bg-[#013DFF]"
                            : "bg-purple-600"
                    }`}
                  >
                    <option value="base">Base</option>
                    <option value="sequential">Sequential</option>
                    <option value="parallel">Parallel</option>
                    <option value="loop">Loop</option>
                  </select>
                </div>
                <div className="flex items-center gap-2">
                  <button
                    onClick={handleSave}
                    disabled={isSaving}
                    className="flex items-center gap-2 px-3 py-1.5 bg-purple-600 hover:bg-purple-700 disabled:bg-purple-800 text-white rounded font-semibold transition-colors text-sm"
                  >
                    <Save size={16} />
                    {isSaving ? "..." : activeTab.isNew ? "Create" : "Save"}
                  </button>
                  <button
                    onClick={() => setExpandedHeader(!expandedHeader)}
                    className="p-1.5 text-gray-400 hover:text-white hover:bg-gray-700 rounded"
                  >
                    {expandedHeader ? (
                      <ChevronUp size={18} />
                    ) : (
                      <ChevronDown size={18} />
                    )}
                  </button>
                </div>
              </div>

              {expandedHeader && (
                <div className="px-4 pb-3 grid grid-cols-2 gap-3 text-sm">
                  <div>
                    <label className="block text-xs text-gray-400 mb-1">
                      Model
                    </label>
                    <input
                      type="text"
                      value={activeTab.agentData.agent_model || ""}
                      onChange={(e) =>
                        updateAgentData({
                          ...activeTab.agentData,
                          agent_model: e.target.value,
                        })
                      }
                      placeholder="e.g. anthropic/claude-sonnet-4-5-20250929"
                      className="w-full px-2 py-1.5 bg-gray-700 text-white rounded border border-gray-600 focus:border-purple-500 focus:outline-none"
                    />
                  </div>
                  <div className="grid grid-cols-2 gap-2">
                    <div>
                      <label className="block text-xs text-gray-400 mb-1">
                        Organization
                      </label>
                      <input
                        type="text"
                        value={activeTab.agentData.organization_id || ""}
                        onChange={(e) =>
                          updateAgentData({
                            ...activeTab.agentData,
                            organization_id: e.target.value,
                          })
                        }
                        placeholder="e.g. thaink2"
                        className="w-full px-2 py-1.5 bg-gray-700 text-white rounded border border-gray-600 focus:border-purple-500 focus:outline-none"
                      />
                    </div>
                    <div>
                      <label className="block text-xs text-gray-400 mb-1">
                        Owner
                      </label>
                      <input
                        type="email"
                        value={activeTab.agentData.owner_id || ""}
                        onChange={(e) =>
                          updateAgentData({
                            ...activeTab.agentData,
                            owner_id: e.target.value,
                          })
                        }
                        placeholder="email@example.com"
                        className="w-full px-2 py-1.5 bg-gray-700 text-white rounded border border-gray-600 focus:border-purple-500 focus:outline-none"
                      />
                    </div>
                  </div>
                  <div>
                    <label className="block text-xs text-gray-400 mb-1">
                      Description
                    </label>
                    <input
                      type="text"
                      value={activeTab.agentData.agent_description || ""}
                      onChange={(e) =>
                        updateAgentData({
                          ...activeTab.agentData,
                          agent_description: e.target.value,
                        })
                      }
                      placeholder="Describe this agent..."
                      className="w-full px-2 py-1.5 bg-gray-700 text-white rounded border border-gray-600 focus:border-purple-500 focus:outline-none"
                    />
                  </div>
                  <div>
                    <label className="block text-xs text-gray-400 mb-1">
                      Instruction
                    </label>
                    <input
                      type="text"
                      value={activeTab.agentData.agent_instruction || ""}
                      onChange={(e) =>
                        updateAgentData({
                          ...activeTab.agentData,
                          agent_instruction: e.target.value,
                        })
                      }
                      placeholder="Instructions for this agent..."
                      className="w-full px-2 py-1.5 bg-gray-700 text-white rounded border border-gray-600 focus:border-purple-500 focus:outline-none"
                    />
                  </div>
                </div>
              )}
            </div>
          )}

          {/* Canvas */}
          <div className="flex-1 overflow-hidden p-4">
            <AgentCanvas
              boxes={boxes}
              canvasBoxes={canvasBoxes}
              availableTools={availableTools}
              onToolChange={() => {}}
              onRun={handleRun}
              onViewDetails={openDetailsModal}
              onEdit={(box) => openAgentTab(box.id)}
              onRemoveFromCanvas={removeFromCanvas}
              onDropFromSidebar={handleDropFromSidebar}
              onReorderCanvas={handleReorderCanvas}
              onDoubleClick={openAgentTab}
              workflowSteps={workflowState.steps}
            />
          </div>

          {/* Workflow Panel */}
          <WorkflowPanel
            workflowState={workflowState}
            onRun={handleRunWorkflow}
            onStop={handleStopWorkflow}
            canvasEmpty={!activeTab || activeTab.canvasOrder.length === 0}
          />
        </div>
      </div>

      {/* Details Modal */}
      {showDetailsModal && viewingAgent && (
        <AgentDetailsModal
          agent={viewingAgent}
          boxes={boxes}
          onClose={closeDetailsModal}
          onViewSubAgent={(subId) => {
            closeDetailsModal();
            openAgentTab(subId);
          }}
        />
      )}

      {/* Delete Confirmation */}
      {deleteConfirm && (
        <ConfirmToast
          message={`Delete "${deleteConfirm.label}" permanently?`}
          onConfirm={confirmDelete}
          onCancel={cancelDelete}
        />
      )}

      {/* Create Agent Modal */}
      <AgentModal
        show={showCreateModal}
        editingAgent={null}
        newAgent={newAgent}
        setNewAgent={setNewAgent}
        boxes={boxes}
        categories={["Base", "Sequential", "Parallel", "Loop"]}
        availableTools={availableTools}
        onClose={closeCreateModal}
        onSave={handleCreateFromModal}
      />
    </div>
  );
}
