"use client";

import { X, GripVertical, Sparkles } from "lucide-react";

export default function AgentModal({
  show,
  editingAgent,
  newAgent,
  setNewAgent,
  boxes,
  categories,
  availableTools = [],
  onClose,
  onSave,
}) {
  if (!show) return null;

  const categoryGlow = {
    Base: "glow-blue",
    Sequential: "glow-purple",
    Parallel: "glow-green",
    Loop: "glow-orange",
  };

  const categoryBorder = {
    Base: "border-[#013DFF]/40",
    Sequential: "border-purple-400/40",
    Parallel: "border-green-400/40",
    Loop: "border-orange-400/40",
  };

  const categoryBg = {
    Base: "bg-blue-500/20",
    Sequential: "bg-purple-500/20",
    Parallel: "bg-green-500/20",
    Loop: "bg-orange-500/20",
  };

  const handleSubAgentToggle = (agentId) => {
    if (newAgent.subAgents.includes(agentId)) {
      setNewAgent((prev) => ({
        ...prev,
        subAgents: prev.subAgents.filter((id) => id !== agentId),
      }));
    } else {
      if (
        ["Sequential", "Parallel"].includes(newAgent.category) &&
        newAgent.subAgents.length >= 6
      ) {
        alert("Maximum 6 sub-agents allowed for Sequential/Parallel agents");
        return;
      }
      setNewAgent((prev) => ({
        ...prev,
        subAgents: [...prev.subAgents, agentId],
      }));
    }
  };

  const moveSubAgentUp = (index) => {
    if (index === 0) return;
    const newSubAgents = [...newAgent.subAgents];
    [newSubAgents[index - 1], newSubAgents[index]] = [
      newSubAgents[index],
      newSubAgents[index - 1],
    ];
    setNewAgent((prev) => ({ ...prev, subAgents: newSubAgents }));
  };

  const moveSubAgentDown = (index) => {
    if (index === newAgent.subAgents.length - 1) return;
    const newSubAgents = [...newAgent.subAgents];
    [newSubAgents[index], newSubAgents[index + 1]] = [
      newSubAgents[index + 1],
      newSubAgents[index],
    ];
    setNewAgent((prev) => ({ ...prev, subAgents: newSubAgents }));
  };

  const handleDragStart = (e, index) => {
    e.dataTransfer.setData("subagent-index", index.toString());
    e.dataTransfer.effectAllowed = "move";
  };

  const handleDragOver = (e, index) => {
    e.preventDefault();
    const fromIndex = parseInt(e.dataTransfer.getData("subagent-index"), 10);
    if (isNaN(fromIndex) || fromIndex === index) return;

    const newSubAgents = [...newAgent.subAgents];
    const draggedItem = newSubAgents[fromIndex];
    newSubAgents.splice(fromIndex, 1);
    newSubAgents.splice(index, 0, draggedItem);

    setNewAgent((prev) => ({ ...prev, subAgents: newSubAgents }));
    e.dataTransfer.setData("subagent-index", index.toString());
  };

  return (
    <div
      className="fixed inset-0 bg-black/50 backdrop-blur-sm flex items-center justify-center z-50 animate-fade-in"
      onClick={onClose}
    >
      <div
        className="glass-modal rounded-2xl p-8 max-w-md w-full mx-4 max-h-[90vh] overflow-y-auto animate-slide-up"
        onClick={(e) => e.stopPropagation()}
      >
        {/* Header */}
        <div className="flex items-center justify-between mb-6">
          <div className="flex items-center gap-3">
            <div className="p-2 rounded-xl bg-purple-500/20 border border-purple-400/30">
              <Sparkles size={20} className="text-purple-400" />
            </div>
            <h2 className="text-2xl font-bold text-white">
              {editingAgent ? "Edit Agent" : "Create Agent"}
            </h2>
          </div>
          <button
            onClick={onClose}
            className="p-2 rounded-xl text-white/40 hover:text-white hover:bg-white/10 transition-all duration-200"
          >
            <X size={20} />
          </button>
        </div>

        {/* Agent Name */}
        <div className="mb-4">
          <label className="block text-sm font-medium text-white/60 mb-2">
            Agent Name *
          </label>
          <input
            type="text"
            value={newAgent.name}
            onChange={(e) => {
              const v = e.target.value;
              setNewAgent((prev) => ({ ...prev, name: v }));
            }}
            placeholder="Enter agent name"
            className="glass-input w-full px-4 py-2.5 rounded-xl"
          />
        </div>

        {/* Category */}
        <div className="mb-4">
          <label className="block text-sm font-medium text-white/60 mb-2">
            Category *
          </label>
          <select
            value={newAgent.category}
            onChange={(e) => {
              const v = e.target.value;
              setNewAgent((prev) => ({
                ...prev,
                category: v,
                subAgents: [],
              }));
            }}
            className={`glass-input w-full px-4 py-2.5 rounded-xl ${categoryBorder[newAgent.category] || ""}`}
          >
            <option value="" className="bg-gray-900 text-white">-- Select Category --</option>
            {categories.map((cat) => (
              <option key={cat} value={cat} className="bg-gray-900 text-white">
                {cat}
              </option>
            ))}
          </select>
          <p className="text-xs text-white/40 mt-1.5">
            {newAgent.category === "Base" &&
              "Single task execution (no sub-agents needed)"}
            {newAgent.category === "Parallel" &&
              "Requires 2-6 sub-agents (executes simultaneously)"}
            {newAgent.category === "Sequential" &&
              "Requires 2-6 sub-agents (executes in order)"}
            {newAgent.category === "Loop" &&
              "Optional sub-agents (repeats until condition)"}
          </p>
        </div>

        {/* Model */}
        <div className="mb-4">
          <label className="block text-sm font-medium text-white/60 mb-2">
            Model *
          </label>
          <input
            type="text"
            value={newAgent.agent_model || ""}
            onChange={(e) => {
              const v = e.target.value;
              setNewAgent((prev) => ({ ...prev, agent_model: v }));
            }}
            placeholder="e.g. anthropic/claude-sonnet-4-5-20250929"
            className="glass-input w-full px-4 py-2.5 rounded-xl"
          />
        </div>

        {/* Description */}
        <div className="mb-4">
          <label className="block text-sm font-medium text-white/60 mb-2">
            Description *
          </label>
          <textarea
            value={newAgent.agent_description || ""}
            onChange={(e) => {
              const v = e.target.value;
              setNewAgent((prev) => ({ ...prev, agent_description: v }));
            }}
            placeholder="Describe the agent"
            rows={2}
            className="glass-input w-full px-4 py-2.5 rounded-xl resize-none"
          />
        </div>

        {/* Instruction */}
        <div className="mb-4">
          <label className="block text-sm font-medium text-white/60 mb-2">
            Instruction *
          </label>
          <textarea
            value={newAgent.agent_instruction || ""}
            onChange={(e) => {
              const v = e.target.value;
              setNewAgent((prev) => ({ ...prev, agent_instruction: v }));
            }}
            placeholder="Instructions for the agent"
            rows={2}
            className="glass-input w-full px-4 py-2.5 rounded-xl resize-none"
          />
        </div>

        {/* Tools */}
        <div className="mb-4">
          <label className="block text-sm font-medium text-white/60 mb-2">
            Tools
          </label>
          <div className="glass-card rounded-xl p-3 max-h-32 overflow-y-auto !transform-none">
            {availableTools.length === 0 ? (
              <p className="text-white/30 text-sm">No tools available</p>
            ) : (
              availableTools.map((tool) => {
                const toolName =
                  typeof tool === "string" ? tool : tool.tool_name || tool.name;
                const selected = (newAgent.agent_tools || []).includes(
                  toolName,
                );
                return (
                  <label
                    key={toolName}
                    className="flex items-center gap-2 p-2 hover:bg-white/5 rounded-lg cursor-pointer transition-colors"
                  >
                    <input
                      type="checkbox"
                      checked={selected}
                      onChange={() => {
                        setNewAgent((prev) => {
                          const current = prev.agent_tools || [];
                          return {
                            ...prev,
                            agent_tools: selected
                              ? current.filter((t) => t !== toolName)
                              : [...current, toolName],
                          };
                        });
                      }}
                      className="rounded accent-purple-500"
                    />
                    <span className="text-sm text-white/70">{toolName}</span>
                  </label>
                );
              })
            )}
          </div>
        </div>

        {/* Org + Owner */}
        <div className="mb-4 grid grid-cols-2 gap-3">
          <div>
            <label className="block text-sm font-medium text-white/60 mb-2">
              Organization ID *
            </label>
            <input
              type="text"
              value={newAgent.organization_id || ""}
              onChange={(e) => {
                const v = e.target.value;
                setNewAgent((prev) => ({ ...prev, organization_id: v }));
              }}
              placeholder="e.g. thaink2"
              className="glass-input w-full px-4 py-2.5 rounded-xl"
            />
          </div>
          <div>
            <label className="block text-sm font-medium text-white/60 mb-2">
              Owner Email *
            </label>
            <input
              type="email"
              value={newAgent.owner_id || ""}
              onChange={(e) => {
                const v = e.target.value;
                setNewAgent((prev) => ({ ...prev, owner_id: v }));
              }}
              placeholder="user@example.com"
              className="glass-input w-full px-4 py-2.5 rounded-xl"
            />
          </div>
        </div>

        {/* Sub-agents */}
        {newAgent.category && newAgent.category !== "Base" && (
          <div className="mb-6">
            <label className="block text-sm font-medium text-white/60 mb-2">
              Sub-agents
              {["Sequential", "Parallel"].includes(newAgent.category) &&
                " (2-6 required) *"}
              {newAgent.category === "Loop" && " (Optional)"}
            </label>

            <div className="glass-card rounded-xl p-3 mb-3 max-h-32 overflow-y-auto !transform-none">
              <p className="text-xs text-white/50 mb-2 font-semibold">
                Available Agents:
              </p>
              {boxes.filter(
                (b) =>
                  b.id !== editingAgent && !newAgent.subAgents.includes(b.id),
              ).length === 0 ? (
                <p className="text-white/30 text-xs">
                  All available agents already selected
                </p>
              ) : (
                boxes
                  .filter(
                    (b) =>
                      b.id !== editingAgent &&
                      !newAgent.subAgents.includes(b.id),
                  )
                  .map((box) => (
                    <button
                      key={box.id}
                      onClick={() => handleSubAgentToggle(box.id)}
                      className="w-full flex items-center mb-2 cursor-pointer hover:bg-white/5 p-2.5 rounded-lg border border-white/10 transition-all duration-200"
                    >
                      <span className="text-sm text-white/70 flex-1 text-left">
                        {box.label}
                      </span>
                      <span
                        className={`text-xs px-2.5 py-1 rounded-lg text-white ${box.color}`}
                      >
                        {box.category}
                      </span>
                    </button>
                  ))
              )}
            </div>

            {newAgent.subAgents.length > 0 && (
              <div className={`rounded-xl p-3 border ${categoryBorder[newAgent.category] || "border-white/10"} ${categoryBg[newAgent.category] || "bg-white/5"}`}>
                <p className="text-xs text-white/50 mb-2 font-semibold">
                  Selected Sub-Agents ({newAgent.subAgents.length}
                  {["Sequential", "Parallel"].includes(newAgent.category) &&
                    " / 2-6"}
                  ):
                  <span className="text-purple-400 ml-2">Drag to reorder</span>
                </p>
                <div className="space-y-2">
                  {newAgent.subAgents.map((subId, index) => {
                    const subAgent = boxes.find((b) => b.id === subId);
                    return (
                      <div
                        key={subId}
                        draggable
                        onDragStart={(e) => handleDragStart(e, index)}
                        onDragOver={(e) => handleDragOver(e, index)}
                        className="flex items-center p-2.5 rounded-lg cursor-move bg-white/5 border border-white/10 hover:border-white/20 transition-all duration-200"
                      >
                        <GripVertical
                          size={16}
                          className="text-white/30 mr-2"
                        />
                        <span className="font-bold text-white/50 mr-2">
                          {index + 1}.
                        </span>
                        <span className="text-sm text-white/80 flex-1">
                          {subAgent ? subAgent.label : subId}
                        </span>
                        {subAgent ? (
                          <span
                            className={`text-xs px-2.5 py-1 rounded-lg text-white ${subAgent.color} mr-2`}
                          >
                            {subAgent.category}
                          </span>
                        ) : (
                          <span className="text-xs px-2.5 py-1 rounded-lg text-white bg-white/20 mr-2">
                            Unknown
                          </span>
                        )}
                        <div className="flex gap-1">
                          <button
                            onClick={() => moveSubAgentUp(index)}
                            disabled={index === 0}
                            className={`p-1 rounded ${index === 0 ? "text-white/20" : "text-white/50 hover:bg-white/10"} transition-colors`}
                            title="Move up"
                          >
                            ▲
                          </button>
                          <button
                            onClick={() => moveSubAgentDown(index)}
                            disabled={index === newAgent.subAgents.length - 1}
                            className={`p-1 rounded ${index === newAgent.subAgents.length - 1 ? "text-white/20" : "text-white/50 hover:bg-white/10"} transition-colors`}
                            title="Move down"
                          >
                            ▼
                          </button>
                          <button
                            onClick={() => handleSubAgentToggle(subId)}
                            className="p-1 text-red-400/70 hover:text-red-400 hover:bg-red-400/10 rounded transition-colors"
                            title="Remove"
                          >
                            ✕
                          </button>
                        </div>
                      </div>
                    );
                  })}
                </div>
              </div>
            )}
          </div>
        )}

        {/* Buttons */}
        <div className="flex gap-3 pt-2">
          <button
            onClick={onClose}
            className="glass-btn flex-1 px-4 py-2.5 border border-white/15 text-white/70 rounded-xl hover:bg-white/10 hover:text-white font-semibold transition-all duration-200"
          >
            Cancel
          </button>
          <button
            onClick={onSave}
            className="glass-btn flex-1 px-4 py-2.5 bg-gradient-to-r from-purple-600 to-violet-600 text-white rounded-xl hover:from-purple-500 hover:to-violet-500 font-semibold transition-all duration-200 shadow-lg shadow-purple-500/20"
          >
            {editingAgent ? "Save Changes" : "Create Agent"}
          </button>
        </div>
      </div>
    </div>
  );
}
