import { createSession, runAgent } from "./api";

/**
 * Run a single agent via the ADK API.
 * Returns the API response object.
 */
async function runSingleAgent(agent, input) {
  const userId = agent.owner_id || "user@example.com";
  const message = input ? JSON.stringify(input) : "Run agent";

  await createSession({
    agent_name: agent.id,
    user_id: userId,
    session_id: agent.id,
  });

  return await runAgent({
    agent_name: agent.id,
    user_id: userId,
    session_id: agent.id,
    run_mode: "run",
    new_message: { role: "user", parts: [{ text: message }] },
  });
}

/**
 * Recursively execute an agent based on its category.
 * - Base: run directly
 * - Sequential (with sub-agents): chain sub-agents, output → input
 * - Parallel (with sub-agents): run all sub-agents simultaneously
 * - Loop: not implemented yet
 *
 * @param {object} agent - The agent object (with id, category, subAgents, etc.)
 * @param {*} input - Input from the previous step (null for first)
 * @param {Map} agentsMap - Map<agentId, agentObject>
 * @param {object} callbacks - { onStepStart, onStepComplete, onStepError }
 * @param {AbortSignal} signal - AbortController signal for cancellation
 */
export async function executeAgent(
  agent,
  input,
  agentsMap,
  callbacks,
  signal,
) {
  if (signal?.aborted) throw new DOMException("Workflow aborted", "AbortError");

  if (agent.category === "Parallel" && agent.subAgents?.length > 0) {
    // Parallel: run all sub-agents simultaneously with the same input
    callbacks.onStepStart(agent.id, "parallel");
    try {
      const results = await Promise.all(
        agent.subAgents.map((subId) => {
          if (signal?.aborted)
            throw new DOMException("Workflow aborted", "AbortError");
          const sub = agentsMap.get(subId);
          if (!sub) return null;
          return executeAgent(sub, input, agentsMap, callbacks, signal);
        }),
      );
      callbacks.onStepComplete(agent.id, results);
      return results;
    } catch (err) {
      callbacks.onStepError(agent.id, err);
      throw err;
    }
  }

  if (agent.category === "Sequential" && agent.subAgents?.length > 0) {
    // Sequential: chain sub-agents, output of one becomes input of next
    callbacks.onStepStart(agent.id, "sequential");
    try {
      let chainedInput = input;
      for (const subId of agent.subAgents) {
        if (signal?.aborted)
          throw new DOMException("Workflow aborted", "AbortError");
        const sub = agentsMap.get(subId);
        if (sub) {
          chainedInput = await executeAgent(
            sub,
            chainedInput,
            agentsMap,
            callbacks,
            signal,
          );
        }
      }
      callbacks.onStepComplete(agent.id, chainedInput);
      return chainedInput;
    } catch (err) {
      callbacks.onStepError(agent.id, err);
      throw err;
    }
  }

  // Base agent (or agent without sub-agents): call API directly
  callbacks.onStepStart(agent.id, "base");
  try {
    const result = await runSingleAgent(agent, input);
    callbacks.onStepComplete(agent.id, result);
    return result;
  } catch (err) {
    callbacks.onStepError(agent.id, err);
    throw err;
  }
}

/**
 * Run the entire canvas workflow.
 * Canvas agents are executed sequentially top-to-bottom,
 * with each agent's output becoming the next's input.
 *
 * @param {string[]} canvasOrder - Ordered agent IDs on the canvas
 * @param {Map} agentsMap - Map<agentId, agentObject>
 * @param {object} callbacks - { onStepStart, onStepComplete, onStepError, onWorkflowStart, onWorkflowComplete, onWorkflowError }
 * @param {AbortSignal} signal - AbortController signal
 */
export async function runWorkflow(
  canvasOrder,
  agentsMap,
  callbacks,
  signal,
) {
  callbacks.onWorkflowStart?.();

  let previousOutput = null;

  try {
    for (const agentId of canvasOrder) {
      if (signal?.aborted)
        throw new DOMException("Workflow aborted", "AbortError");

      const agent = agentsMap.get(agentId);
      if (!agent) continue;

      const result = await executeAgent(
        agent,
        previousOutput,
        agentsMap,
        callbacks,
        signal,
      );
      previousOutput = result;
    }

    callbacks.onWorkflowComplete?.(previousOutput);
    return previousOutput;
  } catch (err) {
    callbacks.onWorkflowError?.(err);
    throw err;
  }
}
