"use client";

import { useState } from "react";
import {
  Eye,
  Edit,
  X,
  Play,
  GripVertical,
  ChevronDown,
  ChevronUp,
  AlertTriangle,
  CheckCircle2,
  Loader2,
  XCircle,
} from "lucide-react";

export default function AgentCanvas({
  boxes,
  canvasBoxes,
  availableTools,
  onToolChange,
  onRun,
  onViewDetails,
  onEdit,
  onRemoveFromCanvas,
  onDropFromSidebar,
  onReorderCanvas,
  onDoubleClick,
  workflowSteps = [],
}) {
  // Build a map for quick step status lookup
  const stepStatusMap = new Map(workflowSteps.map((s) => [s.id, s.status]));
  // Track which agents have collapsed sub-agents (expanded by default)
  const [collapsedAgents, setCollapsedAgents] = useState({});

  const toggleCollapse = (agentId) => {
    setCollapsedAgents((prev) => ({
      ...prev,
      [agentId]: !prev[agentId],
    }));
  };

  // Detect issues with an agent
  const getAgentIssues = (agent) => {
    const issues = [];

    // Check for missing sub-agents
    if (agent.subAgents && agent.subAgents.length > 0) {
      const missingSubs = agent.subAgents.filter(
        (subId) => !boxes.find((b) => b.id === subId),
      );
      if (missingSubs.length > 0) {
        issues.push(`Sub-agent(s) manquant(s): ${missingSubs.join(", ")}`);
      }
    }

    // Check for missing model
    if (!agent.agent_model || agent.agent_model.trim() === "") {
      issues.push("Modèle non défini");
    }

    // Check for empty name
    if (!agent.label || agent.label.trim() === "") {
      issues.push("Nom de l'agent vide");
    }

    // Check if Sequential/Parallel has no sub-agents
    if (
      (agent.category === "Sequential" || agent.category === "Parallel") &&
      (!agent.subAgents || agent.subAgents.length === 0)
    ) {
      issues.push(`Agent ${agent.category} sans sub-agents`);
    }

    return issues;
  };

  const handleDragOver = (e) => {
    e.preventDefault();
    e.dataTransfer.dropEffect = "copy";
  };

  const handleDrop = (e) => {
    e.preventDefault();
    const agentId = e.dataTransfer.getData("agent-id");
    if (!agentId) return;
    onDropFromSidebar(agentId);
  };

  const handleReorderDragStart = (e, index) => {
    e.dataTransfer.setData("reorder-index", index.toString());
    e.dataTransfer.effectAllowed = "move";
  };

  const handleReorderDrop = (e, toIndex) => {
    e.preventDefault();
    e.stopPropagation();
    const fromIndex = parseInt(e.dataTransfer.getData("reorder-index"), 10);
    if (isNaN(fromIndex) || fromIndex === toIndex) return;
    onReorderCanvas(fromIndex, toIndex);
  };

  const categoryColors = {
    Base: "bg-blue-500",
    Parallel: "bg-green-500",
    Sequential: "bg-purple-500",
    Loop: "bg-orange-500",
  };

  // Render a sub-agent mini-card
  const renderSubAgentCard = (
    subAgent,
    subIndex,
    isParallel,
    totalSubAgents,
  ) => {
    if (!subAgent) return null;

    return (
      <div key={subAgent.id} className="flex flex-col items-center">
        <div
          onDoubleClick={(e) => {
            e.stopPropagation();
            onDoubleClick && onDoubleClick(subAgent.id);
          }}
          className={`${categoryColors[subAgent.category] || "bg-gray-500"} text-white rounded-lg p-2 shadow cursor-pointer hover:brightness-110 transition-all ${
            isParallel ? "min-w-[120px]" : "w-full"
          }`}
        >
          <div className="flex items-center justify-between gap-2">
            <p className="font-semibold text-sm truncate">{subAgent.label}</p>
            <div className="flex gap-0.5 shrink-0">
              <button
                onClick={(e) => {
                  e.stopPropagation();
                  onViewDetails(subAgent.id);
                }}
                className="hover:bg-white/20 rounded p-0.5 transition-colors"
                title="View Details"
              >
                <Eye size={12} />
              </button>
              <button
                onClick={(e) => {
                  e.stopPropagation();
                  onEdit(subAgent);
                }}
                className="hover:bg-white/20 rounded p-0.5 transition-colors"
                title="Edit"
              >
                <Edit size={12} />
              </button>
            </div>
          </div>
          <p className="text-[10px] opacity-75">
            {subAgent.category}
            {subAgent.subAgents?.length > 0 &&
              ` • ${subAgent.subAgents.length} sub`}
          </p>
        </div>
        {/* Arrow for sequential sub-agents */}
        {!isParallel && subIndex < totalSubAgents - 1 && (
          <div className="text-white/50 text-xs py-0.5">↓</div>
        )}
      </div>
    );
  };

  return (
    <div
      className="relative bg-gray-100 rounded-xl shadow-2xl overflow-y-auto flex-1 h-full"
      onDragOver={handleDragOver}
      onDrop={handleDrop}
    >
      {canvasBoxes.length === 0 ? (
        <div className="absolute inset-0 flex items-center justify-center">
          <p className="text-gray-400 text-xl">
            Drag agents from the sidebar to build the sequence
          </p>
        </div>
      ) : (
        <div className="flex flex-col items-center py-8 px-4 gap-0">
          {canvasBoxes.map((box, index) => {
            const hasSubAgents = box.subAgents && box.subAgents.length > 0;
            const isCollapsed = collapsedAgents[box.id];
            const isExpandable =
              hasSubAgents &&
              (box.category === "Sequential" || box.category === "Parallel");
            const issues = getAgentIssues(box);
            const hasIssues = issues.length > 0;
            const stepStatus = stepStatusMap.get(box.id);

            // Workflow status ring classes
            const statusRing =
              stepStatus === "running"
                ? "ring-2 ring-yellow-400 animate-pulse"
                : stepStatus === "done"
                  ? "ring-2 ring-green-400"
                  : stepStatus === "error"
                    ? "ring-2 ring-red-400"
                    : "";

            return (
              <div
                key={box.id}
                className="flex flex-col items-center w-full max-w-md"
              >
                {/* Agent card */}
                <div
                  draggable
                  onDragStart={(e) => handleReorderDragStart(e, index)}
                  onDragOver={(e) => {
                    e.preventDefault();
                    e.stopPropagation();
                  }}
                  onDrop={(e) => handleReorderDrop(e, index)}
                  onDoubleClick={() => onDoubleClick && onDoubleClick(box.id)}
                  className={`w-full ${categoryColors[box.category] || "bg-gray-500"} text-white rounded-xl shadow-lg p-4 cursor-grab active:cursor-grabbing transition-transform hover:scale-[1.02] ${statusRing}`}
                >
                  <div className="flex items-start gap-3">
                    <div className="flex flex-col items-center mt-1 shrink-0">
                      {stepStatus === "running" ? (
                        <Loader2 size={18} className="animate-spin opacity-75" />
                      ) : stepStatus === "done" ? (
                        <CheckCircle2 size={18} className="text-green-200" />
                      ) : stepStatus === "error" ? (
                        <XCircle size={18} className="text-red-200" />
                      ) : (
                        <GripVertical size={18} className="opacity-50" />
                      )}
                    </div>

                    <div className="flex-1 min-w-0">
                      <div className="flex items-center justify-between mb-1">
                        <div className="flex items-center gap-2">
                          <p className="font-bold text-lg truncate">
                            {box.label}
                          </p>
                          {/* Warning badge */}
                          {hasIssues && (
                            <div className="relative group">
                              <div className="p-1 bg-yellow-500 rounded-full cursor-help animate-pulse">
                                <AlertTriangle
                                  size={12}
                                  className="text-yellow-900"
                                />
                              </div>
                              {/* Tooltip */}
                              <div className="absolute left-0 top-full mt-1 z-50 hidden group-hover:block w-max max-w-[250px]">
                                <div className="bg-gray-900 text-white text-xs rounded-lg p-2 shadow-lg border border-yellow-500">
                                  <p className="font-semibold text-yellow-400 mb-1">
                                    ⚠️ Problème(s) détecté(s)
                                  </p>
                                  <ul className="list-disc list-inside space-y-0.5">
                                    {issues.map((issue, i) => (
                                      <li key={i}>{issue}</li>
                                    ))}
                                  </ul>
                                </div>
                              </div>
                            </div>
                          )}
                        </div>
                        <div className="flex gap-1 shrink-0">
                          {/* Collapse/Expand button */}
                          {isExpandable && (
                            <button
                              onClick={(e) => {
                                e.stopPropagation();
                                toggleCollapse(box.id);
                              }}
                              className="hover:bg-white/20 rounded p-1.5 transition-colors"
                              title={
                                isCollapsed
                                  ? "Show sub-agents"
                                  : "Hide sub-agents"
                              }
                            >
                              {isCollapsed ? (
                                <ChevronDown size={14} />
                              ) : (
                                <ChevronUp size={14} />
                              )}
                            </button>
                          )}
                          <button
                            onClick={(e) => {
                              e.stopPropagation();
                              onViewDetails(box.id);
                            }}
                            className="hover:bg-white/20 rounded p-1.5 transition-colors"
                            title="View Details"
                          >
                            <Eye size={14} />
                          </button>
                          <button
                            onClick={(e) => {
                              e.stopPropagation();
                              onEdit(box);
                            }}
                            className="hover:bg-white/20 rounded p-1.5 transition-colors"
                            title="Edit"
                          >
                            <Edit size={14} />
                          </button>
                          <button
                            onClick={(e) => {
                              e.stopPropagation();
                              onRemoveFromCanvas(box.id);
                            }}
                            className="hover:bg-white/20 rounded p-1.5 transition-colors"
                            title="Remove from diagram"
                          >
                            <X size={14} />
                          </button>
                        </div>
                      </div>

                      <p className="text-xs opacity-75 font-semibold mb-2">
                        {box.category}
                        {hasSubAgents &&
                          ` • ${box.subAgents.length} sub-agent(s)`}
                      </p>

                      <div className="flex items-center gap-2 mb-2">
                        <select
                          value={box.selectedTool}
                          onChange={(e) => onToolChange(box.id, e.target.value)}
                          className="flex-1 px-2 py-1 rounded text-sm text-gray-800 bg-white border border-white/20 focus:outline-none"
                          onClick={(e) => e.stopPropagation()}
                        >
                          <option value="">-- Tool --</option>
                          {availableTools.map((tool) => (
                            <option key={tool} value={tool}>
                              {tool}
                            </option>
                          ))}
                        </select>
                        <button
                          onClick={(e) => {
                            e.stopPropagation();
                            onRun(box);
                          }}
                          className="bg-white/20 hover:bg-white/30 text-white font-semibold py-1 px-3 rounded-lg transition-colors flex items-center gap-1 border border-white/30 text-sm shrink-0"
                        >
                          <Play size={14} />
                          Run
                        </button>
                      </div>

                      {/* Sub-agents inside the card */}
                      {isExpandable && !isCollapsed && (
                        <div className="bg-black/20 rounded-lg p-3 mt-2">
                          {box.category.toLowerCase() === "parallel" ? (
                            // Parallel: show side by side
                            <div className="flex flex-wrap gap-2 justify-center">
                              {box.subAgents.map((subId, subIndex) => {
                                const subAgent = boxes.find(
                                  (b) => b.id === subId,
                                );
                                if (!subAgent) {
                                  return (
                                    <div
                                      key={subId}
                                      className="bg-gray-500 text-white rounded-lg p-2 text-xs opacity-75"
                                    >
                                      {subId}
                                    </div>
                                  );
                                }
                                return renderSubAgentCard(
                                  subAgent,
                                  subIndex,
                                  true,
                                  box.subAgents.length,
                                );
                              })}
                            </div>
                          ) : (
                            // Sequential: show with arrows
                            <div className="flex flex-col items-center gap-0">
                              {box.subAgents.map((subId, subIndex) => {
                                const subAgent = boxes.find(
                                  (b) => b.id === subId,
                                );
                                if (!subAgent) {
                                  return (
                                    <div
                                      key={subId}
                                      className="flex flex-col items-center"
                                    >
                                      <div className="bg-gray-500 text-white rounded-lg p-2 text-xs opacity-75">
                                        {subId}
                                      </div>
                                      {subIndex < box.subAgents.length - 1 && (
                                        <div className="text-white/50 text-xs py-0.5">
                                          ↓
                                        </div>
                                      )}
                                    </div>
                                  );
                                }
                                return renderSubAgentCard(
                                  subAgent,
                                  subIndex,
                                  false,
                                  box.subAgents.length,
                                );
                              })}
                            </div>
                          )}
                        </div>
                      )}

                      <div className="text-[10px] text-white/50 mt-2 text-center">
                        Step {index + 1}
                      </div>
                    </div>
                  </div>
                </div>

                {/* Arrow between cards */}
                {index < canvasBoxes.length - 1 && (
                  <div className="flex flex-col items-center py-1">
                    <div className="w-0.5 h-6 bg-gray-400"></div>
                    <div className="text-gray-400 text-lg">▼</div>
                  </div>
                )}
              </div>
            );
          })}
        </div>
      )}
    </div>
  );
}
