"use client";

import {
  Play,
  Square,
  RotateCcw,
  CheckCircle2,
  XCircle,
  Loader2,
  Clock,
  ChevronDown,
  ChevronUp,
} from "lucide-react";
import { useState } from "react";

const statusIcons = {
  pending: <Clock size={14} className="text-gray-400" />,
  running: <Loader2 size={14} className="text-yellow-400 animate-spin" />,
  done: <CheckCircle2 size={14} className="text-green-400" />,
  error: <XCircle size={14} className="text-red-400" />,
};

export default function WorkflowPanel({
  workflowState,
  onRun,
  onStop,
  canvasEmpty,
}) {
  const [expandedStep, setExpandedStep] = useState(null);

  const { status, steps, error } = workflowState;
  const isRunning = status === "running";
  const isDone = status === "done";
  const isError = status === "error";

  return (
    <div className="bg-gray-900 border-t border-gray-700 flex flex-col">
      {/* Header bar */}
      <div className="flex items-center justify-between px-4 py-2 border-b border-gray-700">
        <div className="flex items-center gap-3">
          <span className="text-sm font-semibold text-white">Workflow</span>
          {isRunning && (
            <span className="text-xs text-yellow-400 flex items-center gap-1">
              <Loader2 size={12} className="animate-spin" />
              Running...
            </span>
          )}
          {isDone && (
            <span className="text-xs text-green-400 flex items-center gap-1">
              <CheckCircle2 size={12} />
              Complete
            </span>
          )}
          {isError && (
            <span className="text-xs text-red-400 flex items-center gap-1">
              <XCircle size={12} />
              Failed
            </span>
          )}
        </div>

        <div className="flex items-center gap-2">
          {isRunning ? (
            <button
              onClick={onStop}
              className="flex items-center gap-1.5 px-3 py-1.5 bg-red-600 hover:bg-red-700 text-white rounded text-sm font-semibold transition-colors"
            >
              <Square size={14} />
              Stop
            </button>
          ) : (
            <button
              onClick={onRun}
              disabled={canvasEmpty}
              className="flex items-center gap-1.5 px-3 py-1.5 bg-green-600 hover:bg-green-700 disabled:bg-gray-600 disabled:text-gray-400 text-white rounded text-sm font-semibold transition-colors"
            >
              <Play size={14} />
              {isDone || isError ? "Re-run" : "Run Workflow"}
            </button>
          )}
        </div>
      </div>

      {/* Steps list */}
      {steps.length > 0 && (
        <div className="max-h-48 overflow-y-auto">
          {steps.map((step) => (
            <div
              key={step.id}
              className={`border-b border-gray-800 ${
                step.status === "running" ? "bg-yellow-900/10" : ""
              } ${step.status === "error" ? "bg-red-900/10" : ""}`}
            >
              <div
                className="flex items-center gap-3 px-4 py-2 cursor-pointer hover:bg-gray-800/50"
                onClick={() =>
                  setExpandedStep(expandedStep === step.id ? null : step.id)
                }
              >
                {statusIcons[step.status]}
                <span className="text-sm text-white flex-1 truncate">
                  {step.label}
                </span>
                {step.type && (
                  <span className="text-[10px] text-gray-500 uppercase">
                    {step.type}
                  </span>
                )}
                {step.duration != null && (
                  <span className="text-xs text-gray-500">
                    {(step.duration / 1000).toFixed(1)}s
                  </span>
                )}
                {step.result != null && (
                  <span>
                    {expandedStep === step.id ? (
                      <ChevronUp size={12} className="text-gray-500" />
                    ) : (
                      <ChevronDown size={12} className="text-gray-500" />
                    )}
                  </span>
                )}
              </div>

              {/* Expanded result */}
              {expandedStep === step.id && step.result != null && (
                <div className="px-4 pb-2">
                  <pre className="text-xs text-gray-400 bg-gray-800 rounded p-2 max-h-32 overflow-auto whitespace-pre-wrap">
                    {typeof step.result === "string"
                      ? step.result
                      : JSON.stringify(step.result, null, 2)}
                  </pre>
                </div>
              )}

              {/* Error message */}
              {expandedStep === step.id && step.error && (
                <div className="px-4 pb-2">
                  <p className="text-xs text-red-400 bg-red-900/20 rounded p-2">
                    {step.error}
                  </p>
                </div>
              )}
            </div>
          ))}
        </div>
      )}

      {/* Global error */}
      {isError && error && (
        <div className="px-4 py-2">
          <p className="text-xs text-red-400">{error}</p>
        </div>
      )}
    </div>
  );
}
