const BASE = "";

async function request(path, options = {}) {
  const url = `${BASE}${path}`;
  const res = await fetch(url, {
    headers: { "Content-Type": "application/json", ...options.headers },
    ...options,
  });

  const text = await res.text();
  let body;
  try {
    body = text ? JSON.parse(text) : {};
  } catch (e) {
    console.error(`[API] Failed to parse JSON response from ${url}:`, text);
    throw new Error(
      `Invalid JSON response from server: ${text.slice(0, 100)}...`,
    );
  }

  if (!res.ok) {
    const errorMessage =
      body.detail || body.message || `API error ${res.status}`;
    console.error(`[API] Error request to ${url} (${res.status}):`, body);
    throw new Error(errorMessage);
  }

  return body;
}

// --- Agents ---
export const listAgents = () => request("/api/agents");

export const getAgent = (id) => request(`/api/agents/${id}`);

export const createAgent = (data) =>
  request("/api/agents", { method: "POST", body: JSON.stringify(data) });

export const deleteAgent = (id) =>
  request(`/api/agents/${id}`, { method: "DELETE" });

// --- Tools ---
export const listTools = () => request("/api/tools");

export const getToolConfig = (id) => request(`/api/tools_configs/${id}`);

export const createToolConfig = (data) =>
  request("/api/tools_configs", { method: "POST", body: JSON.stringify(data) });

// --- Sessions ---
export const createSession = (data) =>
  request("/api/sessions", { method: "POST", body: JSON.stringify(data) });

export const updateSession = (agentName, userId, sessionId, data) =>
  request(`/api/sessions/${agentName}/${userId}/${sessionId}`, {
    method: "PATCH",
    body: JSON.stringify(data),
  });

export const deleteSession = (agentName, userId, sessionId) =>
  request(`/api/sessions/${agentName}/${userId}/${sessionId}`, {
    method: "DELETE",
  });

// --- Runs ---
export const runAgent = (data) =>
  request("/api/run", { method: "POST", body: JSON.stringify(data) });
