"use client";

import { X, Eye } from "lucide-react";

export default function AgentDetailsModal({
  agent,
  boxes,
  onClose,
  onViewSubAgent,
}) {
  if (!agent) return null;

  return (
    <div
      className="fixed inset-0 bg-black/30 backdrop-blur-sm flex items-center justify-center z-50"
      onClick={onClose}
    >
      <div
        className="bg-white rounded-xl shadow-2xl p-8 max-w-lg w-full mx-4"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="flex items-center justify-between mb-6">
          <h2 className="text-2xl font-bold text-gray-800">Agent Details</h2>
          <button
            onClick={onClose}
            className="text-gray-500 hover:text-gray-700 transition-colors"
          >
            <X size={24} />
          </button>
        </div>

        <div className="space-y-4">
          <div className={`${agent.color} text-white rounded-lg p-4`}>
            <p className="text-2xl font-bold text-center">{agent.label}</p>
            <p className="text-center opacity-90 mt-1">
              {agent.category} Agent
            </p>
          </div>

          <div className="bg-gray-50 rounded-lg p-4">
            <h3 className="font-semibold text-gray-700 mb-3">
              Basic Information
            </h3>
            <div className="space-y-2">
              <div className="flex justify-between">
                <span className="text-gray-600">ID:</span>
                <span className="font-mono text-sm">{agent.id}</span>
              </div>
              <div className="flex justify-between">
                <span className="text-gray-600">Category:</span>
                <span
                  className={`px-2 py-1 rounded text-white text-sm ${agent.color}`}
                >
                  {agent.category}
                </span>
              </div>
              <div className="flex justify-between">
                <span className="text-gray-600">Selected Tool:</span>
                <span className="font-semibold">
                  {agent.selectedTool || "None"}
                </span>
              </div>
              <div className="flex justify-between">
                <span className="text-gray-600">Position:</span>
                <span className="font-mono text-sm">
                  ({Math.round(agent.x)}, {Math.round(agent.y)})
                </span>
              </div>
            </div>
          </div>

          {agent.subAgents.length > 0 && (
            <div className="bg-gray-50 rounded-lg p-4">
              <h3 className="font-semibold text-gray-700 mb-3">
                Sub-Agents ({agent.subAgents.length})
              </h3>
              <div className="space-y-2">
                {agent.subAgents.map((subId, index) => {
                  const subAgent = boxes.find((b) => b.id === subId);
                  if (!subAgent) return null;
                  return (
                    <div
                      key={subId}
                      className="flex items-center justify-between bg-white rounded p-3 border border-gray-200"
                    >
                      <div className="flex items-center gap-3">
                        <span className="font-bold text-gray-600">
                          {index + 1}.
                        </span>
                        <div>
                          <p className="font-semibold text-gray-800">
                            {subAgent.label}
                          </p>
                          <p className="text-xs text-gray-500">
                            {subAgent.category} •{" "}
                            {subAgent.selectedTool || "No tool"}
                          </p>
                        </div>
                      </div>
                      <button
                        onClick={() => onViewSubAgent(subId)}
                        className="text-[#013DFF] hover:text-blue-800"
                        title="View this agent"
                      >
                        <Eye size={18} />
                      </button>
                    </div>
                  );
                })}
              </div>
            </div>
          )}

          <div className="bg-blue-50 rounded-lg p-4">
            <h3 className="font-semibold text-gray-700 mb-2">Behavior</h3>
            <p className="text-sm text-gray-600">
              {agent.category === "Base" &&
                "This is a base agent that executes a single task independently."}
              {agent.category === "Parallel" &&
                "This agent executes all its sub-agents simultaneously in parallel."}
              {agent.category === "Sequential" &&
                "This agent executes its sub-agents one after another in the specified order."}
              {agent.category === "Loop" &&
                "This agent repeatedly executes its sub-agents until a termination condition is met."}
            </p>
          </div>
        </div>

        <button
          onClick={onClose}
          className="w-full mt-6 px-4 py-3 bg-[#013DFF] text-white rounded-lg hover:bg-blue-700 transition-colors font-semibold"
        >
          Close
        </button>
      </div>
    </div>
  );
}
