"use client";

import { ChevronDown, ChevronUp, Save } from "lucide-react";
import { useState } from "react";

export default function AgentHeader({
  agentData,
  onChange,
  onSave,
  isSaving,
  isNew,
  availableTools = [],
}) {
  const [expanded, setExpanded] = useState(true);

  const handleChange = (field, value) => {
    onChange({ ...agentData, [field]: value });
  };

  return (
    <div className="bg-gray-800 border-b border-gray-700">
      {/* Header Bar */}
      <div className="flex items-center justify-between px-6 py-3">
        <div className="flex items-center gap-4 flex-1">
          <input
            type="text"
            value={agentData.agent_name || ""}
            onChange={(e) => handleChange("agent_name", e.target.value)}
            placeholder="Agent Name"
            className="text-2xl font-bold bg-transparent text-white border-b border-transparent hover:border-gray-500 focus:border-blue-500 focus:outline-none px-1"
          />
          <span className="text-xs px-2 py-1 rounded bg-purple-600 text-white">
            Sequential
          </span>
        </div>
        <div className="flex items-center gap-2">
          <button
            onClick={onSave}
            disabled={isSaving}
            className="flex items-center gap-2 px-4 py-2 bg-[#013DFF] hover:bg-blue-700 disabled:bg-blue-800 text-white rounded-lg font-semibold transition-colors"
          >
            <Save size={18} />
            {isSaving ? "Saving..." : isNew ? "Create" : "Save"}
          </button>
          <button
            onClick={() => setExpanded(!expanded)}
            className="p-2 text-gray-400 hover:text-white hover:bg-gray-700 rounded"
          >
            {expanded ? <ChevronUp size={20} /> : <ChevronDown size={20} />}
          </button>
        </div>
      </div>

      {/* Expandable Details */}
      {expanded && (
        <div className="px-6 pb-4 grid grid-cols-2 gap-4">
          {/* Left Column */}
          <div className="space-y-3">
            <div>
              <label className="block text-xs text-gray-400 mb-1">Model</label>
              <input
                type="text"
                value={agentData.agent_model || ""}
                onChange={(e) => handleChange("agent_model", e.target.value)}
                placeholder="e.g. anthropic/claude-sonnet-4-5-20250929"
                className="w-full px-3 py-2 bg-gray-700 text-white rounded border border-gray-600 focus:border-blue-500 focus:outline-none"
              />
            </div>
            <div>
              <label className="block text-xs text-gray-400 mb-1">
                Description
              </label>
              <textarea
                value={agentData.agent_description || ""}
                onChange={(e) =>
                  handleChange("agent_description", e.target.value)
                }
                placeholder="Describe this agent..."
                rows={2}
                className="w-full px-3 py-2 bg-gray-700 text-white rounded border border-gray-600 focus:border-blue-500 focus:outline-none resize-none"
              />
            </div>
            <div>
              <label className="block text-xs text-gray-400 mb-1">
                Instruction
              </label>
              <textarea
                value={agentData.agent_instruction || ""}
                onChange={(e) =>
                  handleChange("agent_instruction", e.target.value)
                }
                placeholder="Instructions for this agent..."
                rows={2}
                className="w-full px-3 py-2 bg-gray-700 text-white rounded border border-gray-600 focus:border-blue-500 focus:outline-none resize-none"
              />
            </div>
          </div>

          {/* Right Column */}
          <div className="space-y-3">
            <div className="grid grid-cols-2 gap-3">
              <div>
                <label className="block text-xs text-gray-400 mb-1">
                  Organization
                </label>
                <input
                  type="text"
                  value={agentData.organization_id || ""}
                  onChange={(e) =>
                    handleChange("organization_id", e.target.value)
                  }
                  placeholder="e.g. thaink2"
                  className="w-full px-3 py-2 bg-gray-700 text-white rounded border border-gray-600 focus:border-blue-500 focus:outline-none"
                />
              </div>
              <div>
                <label className="block text-xs text-gray-400 mb-1">
                  Owner Email
                </label>
                <input
                  type="email"
                  value={agentData.owner_id || ""}
                  onChange={(e) => handleChange("owner_id", e.target.value)}
                  placeholder="user@example.com"
                  className="w-full px-3 py-2 bg-gray-700 text-white rounded border border-gray-600 focus:border-blue-500 focus:outline-none"
                />
              </div>
            </div>
            <div>
              <label className="block text-xs text-gray-400 mb-1">Tools</label>
              <div className="flex flex-wrap gap-2 p-2 bg-gray-700 rounded border border-gray-600 max-h-24 overflow-y-auto">
                {availableTools.length === 0 ? (
                  <span className="text-gray-500 text-sm">
                    No tools available
                  </span>
                ) : (
                  availableTools.map((tool) => {
                    const selected = (agentData.agent_tools || []).includes(
                      tool,
                    );
                    return (
                      <button
                        key={tool}
                        onClick={() => {
                          const current = agentData.agent_tools || [];
                          handleChange(
                            "agent_tools",
                            selected
                              ? current.filter((t) => t !== tool)
                              : [...current, tool],
                          );
                        }}
                        className={`px-2 py-1 rounded text-xs transition-colors ${
                          selected
                            ? "bg-[#013DFF] text-white"
                            : "bg-gray-600 text-gray-300 hover:bg-gray-500"
                        }`}
                      >
                        {tool}
                      </button>
                    );
                  })
                )}
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
