"use client";

import { Trash2, X } from "lucide-react";

export default function ConfirmToast({ message, onConfirm, onCancel }) {
  if (!message) return null;

  return (
    <div className="fixed bottom-6 left-1/2 -translate-x-1/2 z-[100] animate-slide-up">
      <div className="bg-gray-900 border border-gray-700 rounded-xl shadow-2xl px-6 py-4 flex items-center gap-4">
        <Trash2 size={20} className="text-red-400 shrink-0" />
        <p className="text-white text-sm">{message}</p>
        <div className="flex gap-2 shrink-0">
          <button
            onClick={onCancel}
            className="px-3 py-1.5 text-sm text-gray-300 hover:text-white border border-gray-600 rounded-lg hover:bg-gray-700 transition-colors"
          >
            Cancel
          </button>
          <button
            onClick={onConfirm}
            className="px-3 py-1.5 text-sm text-white bg-red-600 hover:bg-red-700 rounded-lg transition-colors font-semibold"
          >
            Delete
          </button>
        </div>
      </div>
    </div>
  );
}
